import SearchResults from './SearchResults';
/**
 * This class is responsible for recursively searching through the
 * packages in the specified root folder (and all packages it links to),
 * and generating a list of ignore-able dependencies. Any package that is
 * a development dependency, but not a production dependency, will be outputted
 * as part of an ignore list.
 *
 * Since the process of generating an ignore list by searching dependencies is
 * a little slow, the results will be cached in an .syncignore-auto file, which will be
 * used on the next execution. However, callers can use a "--force" option to
 * override this and require the search.
 * @class SyncIgnore
 * @param  {string} cwd working folder to use; otherwise use current working directory
 */
export default class SyncIgnore {
    /**
     * The current working directory
     * @name SyncIgnore#_cwd
     * @private
     * @type {String}
     */
    private _cwd;
    /**
     * If should add some extra debugging logs
     * @name SyncIgnore#_debug
     * @private
     * @type {String}
     */
    private _debug;
    /**
     * Get the default file name
     * @name SyncIgnore.FILENAME
     * @default .syncignore-auto
     * @type {string}
     */
    static readonly FILENAME: string;
    /**
     * Get the default file name for manual files.
     * @name SyncIgnore.FILENAME_LOCAL
     * @default .syncignore
     * @type {string}
     */
    static readonly FILENAME_LOCAL: string;
    /**
     * This is helper node.js script for launching the SyncIgnore utility. It can be used
     * for testing.
     *
     * Run it from the package that you want to generate an ignore list for. The output
     * will be a list of files sent to stdout. The same list will appear in the .syncignore-auto
     * file.
     *
     * Parameters:
     *   --force: forces the search process; if not set, the contents of .syncignore-auto
     *            (if present) will be used.
     *   --verbose or --debug: print out debugging info
     *   --empty: creates an empty .syncignore-auto file
     * @method SyncIgnore.cli
     */
    static cli(): void;
    /**
     * Constructs SyncIgnore instance
     */
    constructor(cwd?: string);
    /**
     * Execute SyncIgnore program
     * @method SyncIgnore#exec
     * @param  {boolean}  force force full search, even if syncignore-auto file
     *                          exists
     * @param  {boolean}  debug if true, debugging info will be printed to
     *                          console log
     * @return {string[]} array of package names (to ignore)
     */
    exec(force: boolean, debug: boolean): string[];
    /**
     * Noop for exec
     * @method SyncIgnore#fakeExec
     * @return {Array<string>} Results
     */
    fakeExec(): string[];
    /**
     * Execute full search of folder tree, with the root being the specified
     * path.
     * @function SyncIgnore#_search
     * @private
     * @param  {string} packagePath root path
     * @return {SearchResults} results The results to update
     */
    _search(packagePath: string, results: SearchResults): void;
    /**
     * Get the rest of the node_modules and add everything else
     * the results should consider anything else that isn't
     * already defined as a production dependency to be dev and ignored.
     * @function SyncIgnore#_searchRemainder
     * @private
     * @param {string} packagePath root path
     * @param {SearchResults} results The results to update
     */
    private _searchRemainder(packagePath, results);
}
